class _ProgressTab extends StatelessWidget { const _ProgressTab({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => FutureBuilder<List<Map<String, dynamic>>>(future: apiService.fetchStudentProgress(), builder: (context, snapshot) { if (snapshot.hasError) return const _LmsState(icon: Icons.cloud_off, text: 'Progress is unavailable right now.'); if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final items = snapshot.data!; if (items.isEmpty) return const _LmsState(icon: Icons.trending_up, text: 'Enroll in a course to start tracking progress.'); return RefreshIndicator(onRefresh: () async { await apiService.fetchStudentProgress(); }, child: ListView(padding: const EdgeInsets.all(16), children: [Text('Your momentum', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 16), ...items.map((item) { final progress = double.tryParse('${item['progress'] ?? 0}') ?? 0; return Card(margin: const EdgeInsets.only(bottom: 12), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Course #${item['project_id'] ?? ''}', style: Theme.of(context).textTheme.titleMedium), const SizedBox(height: 12), LinearProgressIndicator(value: progress / 100, minHeight: 8), const SizedBox(height: 8), Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text('${progress.toStringAsFixed(0)}% complete'), Text('${item['lesson_count'] ?? 0} lessons')]), const SizedBox(height: 8), Text('${item['submitted_count'] ?? 0} submissions  |  ${item['graded_count'] ?? 0} graded')]))); })])); }); }

class _GradesTab extends StatelessWidget { const _GradesTab({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => FutureBuilder<List<Map<String, dynamic>>>(future: apiService.fetchGrades(), builder: (context, snapshot) { if (snapshot.hasError) return const _LmsState(icon: Icons.cloud_off, text: 'Grades are unavailable right now.'); if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final items = snapshot.data!; if (items.isEmpty) return const _LmsState(icon: Icons.grading_outlined, text: 'Your graded assignments will appear here.'); return ListView(padding: const EdgeInsets.all(16), children: items.map((item) => Card(child: ListTile(leading: const Icon(Icons.grading_outlined), title: Text('${item['assignment_title'] ?? 'Assignment'}'), subtitle: Text('${item['course_title'] ?? 'Course'}\n${item['feedback'] ?? 'No feedback yet'}'), isThreeLine: true, trailing: Text(item['score'] == null ? 'Pending' : '${item['score']}/${item['max_score'] ?? 100}', style: const TextStyle(fontWeight: FontWeight.bold)))).toList()); }); }

class _CurriculumTab extends StatelessWidget { const _CurriculumTab({required this.apiService}); final ApiService apiService; @override Widget build(BuildContext context) => FutureBuilder<List<Map<String, dynamic>>>(future: apiService.fetchMyCourses(), builder: (context, snapshot) { if (snapshot.hasError) return const _LmsState(icon: Icons.cloud_off, text: 'Curriculum is unavailable right now.'); if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final courses = snapshot.data!; if (courses.isEmpty) return const _LmsState(icon: Icons.account_tree_outlined, text: 'Your enrolled curriculum will appear here.'); return ListView(padding: const EdgeInsets.all(16), children: courses.map((course) => _CurriculumCourse(apiService: apiService, course: course)).toList()); }); }

class _CurriculumCourse extends StatefulWidget { const _CurriculumCourse({required this.apiService, required this.course}); final ApiService apiService; final Map<String, dynamic> course; @override State<_CurriculumCourse> createState() => _CurriculumCourseState(); }
class _CurriculumCourseState extends State<_CurriculumCourse> { bool _expanded = false; Map<String, dynamic>? _details; bool _loading = false; Future<void> _open() async { setState(() { _expanded = !_expanded; _loading = true; }); if (!_expanded) return; try { final data = await widget.apiService.fetchCourse(int.parse('${widget.course['project_id']}')); if (mounted) setState(() => _details = data); } catch (_) {} finally { if (mounted) setState(() => _loading = false); } } @override Widget build(BuildContext context) { final lessons = (_details?['lessons'] as List? ?? []).map((item) => Map<String, dynamic>.from(item as Map)).toList(); return Card(child: Column(children: [ListTile(title: Text('${widget.course['course_title'] ?? 'Course'}'), subtitle: Text('${widget.course['progress'] ?? 0}% complete'), trailing: IconButton(onPressed: _open, icon: Icon(_expanded ? Icons.expand_less : Icons.expand_more), tooltip: 'Show curriculum')), if (_expanded) _loading ? const Padding(padding: EdgeInsets.all(16), child: CircularProgressIndicator()) : lessons.isEmpty ? const Padding(padding: EdgeInsets.all(16), child: Text('No lessons published yet.')) : ...lessons.map((lesson) => ListTile(dense: true, leading: Icon(lesson['type'] == 'Video' ? Icons.play_circle_outline : Icons.description_outlined), title: Text('${lesson['title'] ?? 'Lesson'}'), subtitle: Text('${lesson['type'] ?? 'Resource'}'), trailing: IconButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => LessonPlayerScreen(apiService: widget.apiService, lesson: lesson))), icon: const Icon(Icons.play_arrow), tooltip: 'Open lesson'))]))); } }

class LessonPlayerScreen extends StatefulWidget { const LessonPlayerScreen({required this.apiService, required this.lesson, super.key}); final ApiService apiService; final Map<String, dynamic> lesson; @override State<LessonPlayerScreen> createState() => _LessonPlayerScreenState(); }
class _LessonPlayerScreenState extends State<LessonPlayerScreen> { VideoPlayerController? _controller; double _watched = 0; double _lastPosition = 0; bool _completed = false; @override void initState() { super.initState(); _restore(); } Future<void> _restore() async { final saved = await widget.apiService.fetchLessonProgress(int.tryParse('${widget.lesson['project_id'] ?? 0}') ?? 0, int.tryParse('${widget.lesson['id'] ?? 0}') ?? 0); if (mounted && saved != null) setState(() { _watched = (double.tryParse('${saved['percentage'] ?? 0}') ?? 0) / 100; _lastPosition = double.tryParse('${saved['position'] ?? 0}') ?? 0; _completed = saved['completed'] == true; }); if (widget.lesson['type'] == 'Video' && '${widget.lesson['file_url'] ?? ''}'.isNotEmpty) { final controller = VideoPlayerController.networkUrl(Uri.parse('${widget.lesson['file_url']}')); try { await controller.initialize(); controller.addListener(_syncVideoProgress); if (mounted) setState(() => _controller = controller); } catch (_) { await controller.dispose(); } } } void _syncVideoProgress() { final controller = _controller; if (controller == null || !controller.value.isInitialized || controller.value.duration.inSeconds == 0) return; final value = controller.value; final watched = value.position.inMilliseconds / value.duration.inMilliseconds; if (mounted) setState(() { _watched = watched.clamp(0, 1); _lastPosition = value.position.inSeconds.toDouble(); }); if (watched >= .9) _save(completed: true); } Future<void> _save({bool completed = false}) async { try { await widget.apiService.trackLesson(courseId: int.tryParse('${widget.lesson['project_id'] ?? 0}') ?? 0, resourceId: int.tryParse('${widget.lesson['id'] ?? 0}') ?? 0, percentage: _watched * 100, position: _lastPosition, completed: completed || _completed); if (mounted && completed) setState(() => _completed = true); } catch (_) {} } @override void dispose() { _save(); _controller?.removeListener(_syncVideoProgress); _controller?.dispose(); super.dispose(); } @override Widget build(BuildContext context) { final controller = _controller; return Scaffold(appBar: AppBar(title: const Text('Lesson player')), body: ListView(padding: const EdgeInsets.all(20), children: [AspectRatio(aspectRatio: controller?.value.aspectRatio ?? 16 / 9, child: Container(color: Theme.of(context).colorScheme.surfaceContainerHighest, child: controller == null ? Center(child: Icon(widget.lesson['type'] == 'Video' ? Icons.video_library_outlined : Icons.description_outlined, size: 58)) : VideoPlayer(controller))), if (controller != null) VideoProgressIndicator(controller, allowScrubbing: true, padding: const EdgeInsets.symmetric(vertical: 12)), if (controller != null) FilledButton.icon(onPressed: () { if (controller.value.isPlaying) { controller.pause(); } else { if (_lastPosition > 0 && controller.value.position == Duration.zero) controller.seekTo(Duration(seconds: _lastPosition.round())); controller.play(); } setState(() {}); }, icon: Icon(controller.value.isPlaying ? Icons.pause : Icons.play_arrow), label: Text(controller.value.isPlaying ? 'Pause video' : 'Play video')), const SizedBox(height: 12), Text('${widget.lesson['title'] ?? 'Lesson'}', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 8), Text('${widget.lesson['description'] ?? 'Work through this lesson at your own pace.'}'), const SizedBox(height: 16), LinearProgressIndicator(value: _watched), const SizedBox(height: 8), Text('${(_watched * 100).round()}% watched  |  ${_completed ? 'Completed' : 'In progress'}'), const SizedBox(height: 12), OutlinedButton.icon(onPressed: () => _save(completed: true), icon: const Icon(Icons.task_alt), label: Text(_completed ? 'Lesson completed' : 'Mark lesson complete')), const SizedBox(height: 12), Text('Last position: ${_lastPosition.round()} seconds'), ])); } }

class _LmsState extends StatelessWidget { const _LmsState({required this.icon, required this.text}); final IconData icon; final String text; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(icon, size: 52, color: Theme.of(context).colorScheme.primary), const SizedBox(height: 12), Text(text, textAlign: TextAlign.center)]))); }
